-- The GROOVE4CUT code key (Code keys -> Parting -> GROOVE4CUT), from the ISCAR
-- e-catalog's GROOVE4CUT families (QGI 30N-PF / -P inserts, QTHR/L-30-JHP-MC
-- tools); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.groove4cut', $ck${"title": "GROOVE4CUT code key – inserts and tools", "subtitle": "Inserts with 4 cutting edges (QGI) for parting and precision grooving, on QTHR/L tools with high-pressure coolant", "example": "QGI 30N200PF020", "decoder": "groove4cut", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "QGI", "rows": [{"code": "QGI", "meaning": "GROOVE4CUT insert with 4 cutting edges"}]}, {"key": "i-size", "title": "Insert – size", "sample": "30", "rows": [{"code": "30", "meaning": "Size 30 (for QTHR/L ...-30 tools)"}]}, {"key": "i-hand", "title": "Hand of insert", "rows": [{"code": "N", "meaning": "Neutral"}, {"code": "R", "meaning": "Right"}, {"code": "L", "meaning": "Left"}], "sample": "N"}, {"key": "i-width", "title": "Insert – cutting width (x100 mm)", "sample": "200", "rows": [{"code": "###", "meaning": "Cutting width x 100 (e.g. 200 = 2.00 mm; 1.00 to 3.00 mm)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "PF", "rows": [{"code": "PF", "meaning": "Positive flat rake – parting and precision grooving"}, {"code": "P", "meaning": "High positive flat rake – parting and precision grooving"}]}, {"key": "i-radius", "title": "Insert – corner radius (x100 mm)", "sample": "020", "rows": [{"code": "###", "meaning": "Corner radius x 100 (e.g. 020 = 0.20 mm; 000 = sharp)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "QTH", "meaning": "Grooving and parting tools for GROOVE4CUT inserts, with high-pressure coolant inlets (QTHR / QTHL)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "t-height", "title": "Tool – shank", "rows": [{"code": "##", "meaning": "Shank size in mm (16, 20, 25)"}]}, {"key": "t-seat", "title": "Tool – insert size", "rows": [{"code": "30", "meaning": "For QGI 30 inserts"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}]}], "tables": [{"title": "QGI 30 inserts (IC1008): cutting width, corner radius, max. cutting depth CDX and feed range fg (e-catalog)", "columns": ["Designation", "CW (mm)", "RE (mm)", "CDX (mm)", "fg (mm/rev)"], "rows": [["QGI 30N100PF006", "1", "0.06", "4", "0.02–0.05"], ["QGI 30N120PF000", "1.2", "0", "5", "0.02–0.07"], ["QGI 30N150PF010", "1.5", "0.1", "7.2", "0.03–0.08"], ["QGI 30N200PF020", "2", "0.2", "7.2", "0.03–0.1"], ["QGI 30N247PF020", "2.47", "0.2", "7.2", "0.03–0.12"], ["QGI 30N250PF020", "2.5", "0.2", "7.2", "0.03–0.12"], ["QGI 30N270PF010", "2.7", "0.1", "7.2", "0.03–0.12"], ["QGI 30N300PF020", "3", "0.2", "7.2", "0.03–0.12"], ["QGI 30N100P005", "1", "0.05", "4", "0.02–0.04"], ["QGI 30N120P005", "1.2", "0.05", "5", "0.02–0.06"], ["QGI 30N150P005", "1.5", "0.05", "7.2", "0.02–0.07"], ["QGI 30N200P005", "2", "0.05", "7.2", "0.02–0.08"], ["QGI 30N247P005", "2.47", "0.05", "7.2", "0.02–0.1"], ["QGI 30N250P005", "2.5", "0.05", "7.2", "0.02–0.1"], ["QGI 30N270P005", "2.7", "0.05", "7.2", "0.02–0.1"], ["QGI 30N300P005", "3", "0.05", "7.2", "0.02–0.1"]]}, {"title": "QTHR/L-30-JHP-MC tools: cutting width 1-3 mm, max. cutting depth CDX 7.3 mm; shank 16 (UNF 5/16-24 coolant inlet), 20 and 25 (G1/8)", "columns": ["Designation", "Shank (mm)", "CW (mm)", "CDX (mm)"], "rows": [["QTHR 16-30-JHP-MC", "16", "1–3", "7.3"], ["QTHL 16-30-JHP-MC", "16", "1–3", "7.3"], ["QTHR 20-30-JHP-MC", "20", "1–3", "7.3"], ["QTHL 20-30-JHP-MC", "20", "1–3", "7.3"], ["QTHR 25-30-JHP-MC", "25", "1–3", "7.3"], ["QTHL 25-30-JHP-MC", "25", "1–3", "7.3"]]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
